  [425754] = { "Ottieni l'abilità Scorticatura:\n\n$I1\nUn attacco ad ampio raggio che colpisce con le armi da mischia tutti i nemici davanti a te, infliggendo il $N1% dei danni dell'arma. Il tuo bersaglio principale subisce il $N2% di danni in più.", nil, 0xc57af772, nil, "um" },
  [425755] = { "Ottieni l'abilità Cobra Strikes:\n\n$I1\nI tuoi colpi critici con le abilità di tiro e di assalto e con Morso della Mangusta rendono critici i prossimi $N1 attacchi speciali del tuo famiglio.", nil, 0xc059b510, nil, "um" },
