  [425757] = { "Ottieni l'abilità Assalto Fiancheggiato:\n\n$I1\nTu e il tuo famiglio infliggete simultaneamente e istantaneamente il $N1% dei danni in mischia. In seguito, infliggi il $N2% di danni in più per $D1, effetto cumulabile fino a $N4 volte. Gli attacchi base del tuo famiglio hanno il $N5% di probabilità di azzerare il tempo di recupero di Assalto Fiancheggiato.", nil, 0xb7bf4b06, nil, "um" },
  [425758] = { "Incidi sui tuoi guanti la runa Scorticatura:\n\n$I1\nUn attacco ad ampio raggio che colpisce con le armi da mischia tutti i nemici davanti a te, infliggendo il $N1% dei danni dell'arma. Il tuo bersaglio principale subisce il $N2% di danni in più.", nil, 0x3c61f546, nil, "um" },
