  [425760] = { "Incidi sui tuoi gambali la runa Serpent Spread:\n\n$I1\nI bersagli colpiti dal tuo Tiro Multiplo vengono afflitti anche dal tuo Morso del Serpente per $D1.", nil, 0x5f415872, nil, "um" },
  [425762] = { "Incidi sui tuoi gambali la runa Assalto Fiancheggiato:\n\n$I1\nTu e il tuo famiglio infliggete simultaneamente e istantaneamente il $N1% dei danni in mischia. In seguito, infliggi il $N2% di danni in più per $D1, effetto cumulabile fino a $N4 volte. Gli attacchi base del tuo famiglio hanno il $N5% di probabilità di azzerare il tempo di recupero di Assalto Fiancheggiato.", nil, 0x2cd65e38, nil, "um" },
  [425798] = { nil, "Questa unità ha saccheggiato da poco il forziere dell'⟦Gurubashi Arena=Arena dei Gurubashi⟧ e per un po' non può reclamarne di nuovo il bottino.", nil, 0x78eb8040, "mu" },
  [425858] = { "Quando curi in modo critico con ⟦Healing Wave=Ondata di Cura⟧ o ⟦Lesser Healing Wave=Ondata di Cura Inferiore⟧, evochi uno spirito ancestrale che ti aiuta curando istantaneamente il membro del gruppo con la percentuale di salute più bassa entro $N1 m del $N2% della quantità curata.", nil, 0xd30bce97, nil, "um" },
  [425864] = { "Quando curi in modo critico con ⟦Healing Wave=Ondata di Cura⟧ o ⟦Lesser Healing Wave=Ondata di Cura Inferiore⟧, evochi uno spirito ancestrale che ti aiuta curando istantaneamente il bersaglio alleato del gruppo o dell'incursione con la percentuale di salute più bassa entro $N1 m.", nil, 0xbc4a8023, nil, "um" },
  [425874] = { "Evoca ai piedi del bersaglio un Decoy Totem con $N2 salute per $D1, che devia sul totem il prossimo attacco in mischia o a distanza sferrato contro il bersaglio. Il totem rende inoltre il bersaglio immune agli effetti di limitazione al movimento per $D2.", nil, 0x4df50519, nil, "um" },
  [425876] = { nil, "Devia un attacco in mischia o a distanza verso il Decoy Totem.", nil, 0x39a46385, "mu" },
